// Two inbound paths land here: the sync response (wrapped by fullResponse, so it has `.body`) and the
// no-change branch (which carries the preview JSON straight through). `.body` is what tells them apart.
const src = $input.first().json;
const preview = $('Preview reverse-ETL diff').first().json;
const sync = src.body ?? null;
const ran = !!(sync && sync.job);
const record = {
  // Empty list: this is an operational record, not GTM data. /api/v1/webhooks/n8n stores the whole body
  // verbatim and hands `signals` to the signal processor, so [] records the run without inventing signals.
  signals: [],
  // Dedupe key. A sync row id is unique per run; a no-op is keyed to the minute so a burst of no-op runs
  // does not create a row per attempt.
  event_id: 'n8n-reverse-etl:' + (ran ? sync.id : 'noop:' + new Date().toISOString().slice(0, 16)),
  record_type: 'reverse_etl_run',
  recorded_by: 'n8n:03-qualified-accounts-to-hubspot',
  recorded_at: new Date().toISOString(),
  n8n_execution_id: $execution.id,
  ran_sync: ran,
  http_status: src.statusCode ?? null,
  preview: {
    considered: preview.considered,
    would_create: preview.would_create,
    would_update: preview.would_update,
    unchanged: preview.unchanged,
    changed_field_counts: preview.changed_field_counts
  },
  sync: ran ? {
    id: sync.id,
    job: sync.job,
    status: sync.status,
    is_simulated: sync.is_simulated,
    records_considered: sync.records_considered,
    records_changed: sync.records_changed,
    records_succeeded: sync.records_succeeded,
    records_failed: sync.records_failed,
    records_skipped: sync.records_skipped,
    duration_ms: sync.duration_ms,
    errors: (sync.errors ?? []).slice(0, 10)
  } : null
};
try {
  $execution.customData.set('gtmos_reverse_etl', ran ? String(sync.status) : 'no_change');
  $execution.customData.set('gtmos_records_changed', String(ran ? sync.records_changed : 0));
} catch (e) { /* telemetry must not break the run */ }
return [{ json: record }];

// X-GTMOS-Signature = sha256=HMAC(secret, `${timestamp}.${rawBody}`); GTMOS rejects >5 min skew.
const crypto = require('crypto');
const secret = $env.GTMOS_WEBHOOK_SECRET;
return $input.all().map((item) => {
  const body = JSON.stringify(item.json);
  const ts = Math.floor(Date.now() / 1000).toString();
  const sig = 'sha256=' + crypto.createHmac('sha256', secret).update(ts + '.' + body).digest('hex');
  return { json: { body, ts, sig } };
});
